-- Generado desde el inventario original: 204 registros, 900 unidades.
-- No fusiona duplicados ni inventa cantidades.
on conflict (id) do update set name=excluded.name, source_name=excluded.source_name, gender=excluded.gender, stock=excluded.stock, min_stock=excluded.min_stock, photo_url=excluded.photo_url, is_active=excluded.is_active, data_status=excluded.data_status;

select setval(pg_get_serial_sequence('public.products','id'), (select max(id) from public.products));
